

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .function_call_item_param_status import FunctionCallItemParamStatus
from .function_call_item_param_type import FunctionCallItemParamType


class FunctionCallItemParam(UniversalBaseModel):
    id: typing.Optional[str] = pydantic.Field(default=None)
    """
    The unique ID of this function tool call.
    """

    call_id: str = pydantic.Field()
    """
    The unique ID of the function tool call generated by the model.
    """

    type: FunctionCallItemParamType = pydantic.Field()
    """
    The item type. Always `function_call`.
    """

    name: str = pydantic.Field()
    """
    The name of the function to call.
    """

    arguments: str = pydantic.Field()
    """
    The function arguments as a JSON string.
    """

    status: typing.Optional[FunctionCallItemParamStatus] = pydantic.Field(default=None)
    """
    The status of the function tool call.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
